import React from 'react';
import {Link, useNavigate} from 'react-router-dom';
import {useDispatch, useSelector} from 'react-redux';
import {Row, Col, ListGroup, Image, Form, Button, Card, Container} from 'react-bootstrap';
import {FaTrash} from 'react-icons/fa';
import Message from '../components/Message';
import {addToCart, removeFromCart} from '../slices/cartSlice';
import '../assets/styles/screens/cartscreen.css'
import Footer from '../components/Footer';

const CartScreen = () => {

    const navigate = useNavigate();
    const dispatch = useDispatch();

    const cart = useSelector((state) => state.cart);
    const {cartItems} = cart;

    const addToCartHandler = (product, qty) => {
        dispatch(addToCart({...product, qty}));
    }

    // Whatevers passed in here is whats passed into the "action payload" in slice
    const removeFromCartHandler = async(id) => {
        dispatch(removeFromCart(id));
    }

    // redirect to login if not logged in, else direct to shipping
    const checkOutHandler = () => {
        navigate('/login?redirect=/shipping');
    }

  return (
    <Container className='cart-container'>
        <Row>
            <Col md={8}>
                <h1 style={{marginBottom: '20px'}}>SHOPPING CART</h1>
                {cartItems.length === 0 ? (
                    <Message>
                        Your cart is empty <Link to='/shop'>Go back</Link>
                    </Message>
                ) : (
                    <ListGroup variant='flush'>
                        {cartItems.map((item) => (
                            <ListGroup.Item key={item._id}>
                                <Row className='cartItems-wrapper'>
                                    <Col md={2}>
                                        <Image src={item.image} alt={item.name} fluid rounded></Image>
                                    </Col>
                                    <Col md={3}>
                                        <Link to={`/product/${item._id}`}>{item.name}</Link>
                                    </Col>
                                    <Col md={2}>
                                        ${(item.price).toFixed(2)}
                                    </Col>
                                    <Col md={2}>
                                        <Form.Control
                                            as='select'
                                            value={item.qty}
                                            onChange={(e) => addToCartHandler(item, Number(e.target.value))}>
                                                {[...Array(item.countInStock).keys()].map((x) => (
                                                    <option key={x + 1} value={x + 1}>
                                                        {x + 1}
                                                    </option>
                                                ))}
                                        </Form.Control>
                                    </Col>
                                    <Col md={2}>
                                        <Button type='button' variant='light' onClick={ () => removeFromCartHandler(item._id)}>
                                            <FaTrash/>
                                        </Button>
                                    </Col>
                                </Row>
                            </ListGroup.Item>
                        ))}
                    </ListGroup>
                )}
            </Col>
            <Col md={4}>
                <Card>
                    <ListGroup variant='flush'>
                        <ListGroup.Item>
                            <h2>
                                SUBTOTAL [{cartItems.reduce((acc, item) => acc + item.qty, 0)}] 
                            </h2>
                            ${cartItems.reduce((acc, item) => acc + item.qty * item.price, 0).toFixed(2)}
                        </ListGroup.Item>
                        <ListGroup.Item>
                            <Button type='button' className='btn-block' disabled={cartItems.length === 0}
                            onClick={checkOutHandler}>
                                Proceed to Checkout
                            </Button>
                        </ListGroup.Item>
                        <ListGroup.Item>
                            <Link className='continueShop-link' to='/shop'>Continue Shopping</Link>
                        </ListGroup.Item>
                    </ListGroup>
                    {/* <ListGroup>
                        <ListGroup.Item>
                            <Link className to='/shop'>Continue Shopping</Link>
                        </ListGroup.Item>
                    </ListGroup> */}
                </Card>
            </Col>
        </Row>
    </Container>
    
  )
}

export default CartScreen